+  for (int i = 0; i < 4; i++) {
+    __ evpsubd(xmm(scratchRegs[i + 4]), k0, xmm(scratchRegs[i]),
+               xmm(scratchRegs[i + 4]), false, Assembler::AVX_512bit);
+  }
+
+  for (int i = 0; i < 4; i++) {
+    __ vpshufd(xmm(inputRegs1[i]), xmm(inputRegs1[i]), 0xB1,
+               Assembler::AVX_512bit);
